import spawn from 'cross-spawn';
/**
 * Run TypeScript type checking (tsc --noEmit)
 * Skips silently if TypeScript not available
 */ export async function runTypeScriptCheck(projectPath, packageManager) {
    return new Promise((resolve)=>{
        try {
            const child = spawn(packageManager, [
                'exec',
                'tsc',
                '--noEmit'
            ], {
                cwd: projectPath,
                stdio: 'pipe'
            });
            let output = '';
            child.stdout?.on('data', (data)=>{
                output += data.toString();
            });
            child.on('close', (code)=>{
                if (code === 0) {
                    resolve({
                        errors: [],
                        success: true
                    });
                } else {
                    const errors = parseTypeScriptErrors(output);
                    resolve({
                        errors,
                        success: false
                    });
                }
            });
            child.on('error', ()=>{
                // tsc not available - skip validation
                resolve({
                    errors: [],
                    success: true
                });
            });
        } catch  {
            // Skip validation if error
            resolve({
                errors: [],
                success: true
            });
        }
    });
}
/**
 * Parse TypeScript error output
 */ function parseTypeScriptErrors(output) {
    return output.split(/\r?\n/).filter((line)=>line.includes('error TS')).map((line)=>line.trim());
}
